#!/usr/bin/env python3
"""Bounded Day8 L2 coherent 2+ -> 2+ -> 0+ cascade, using existing RB input.

Default: run exact checks and print a compact result.  --write-receipt creates
one new owned JSON exclusively; it never updates prior artifacts or Wiki state.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
from functools import lru_cache
import hashlib
import json
from pathlib import Path
import platform
import sys
import time

sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[4]
DEPS = ROOT / 'tmp/day8-20261007/rose-brink/python-deps'
sys.path.insert(0, str(DEPS))
import sympy as sp
from sympy.physics.wigner import clebsch_gordan, racah, wigner_d_small

RUN = ROOT / 'outputs/learning-daily/20261007-DAY8-angular-momentum-selection-rules-multipolarity-run-01'
INPUT = RUN / 'four-multipole-fixed-population-pair.json'
OUTPUT = RUN / 'cascade-companion-discriminant.json'
SOURCE = ROOT / 'knowledge/sources/rose-brink-1967-phase-defined-angular-distributions.md'
RAW = ROOT / 'raw/papers/gpt/high-spin-20260920/multipolarity/mixing ratio/1967_Rose et al_Angular Distributions of Gamma Rays in Terms of Phase-Defined Reduced Matrix Elements.pdf'
INPUT_SHA = 'b5a7ea2f727264b9d3ff56f4fec25302d326baab1ec67fd9774dea3d2522b8fd'
RAW_SHA = '8f846b61b9320de291ee5600126c5e286a0fe05968df819696816f0dc1ec57dc'
M = tuple(range(-2, 3))
Q = (-1, 1)
PI = (1, 0, 1, 0)
WEIGHTS = (sp.Rational(1, 4), sp.Rational(1, 8), sp.Rational(1, 4), sp.Rational(1, 8), sp.Rational(1, 4))
RANDOM = (sp.Rational(1, 5),) * 5
X, Y = sp.symbols('cos_theta sin_theta', real=True)


def ex(value):
    """Expand real square-root expressions without using numerical tolerances."""
    return sp.expand(value)


def mx(matrix):
    return matrix.applyfunc(ex)


def is_zero_matrix(matrix):
    return mx(matrix) == sp.zeros(matrix.rows, matrix.cols)


def text_scalar(value):
    return sp.sstr(value)


def serial_matrix(matrix):
    return [[text_scalar(matrix[i, j]) for j in range(matrix.cols)] for i in range(matrix.rows)]


def serial_vector(vector):
    return [text_scalar(value) for value in vector]


def display(value):
    return str(sp.N(value, 14))


@lru_cache(None)
def cg(L, i, m):
    return clebsch_gordan(2, L, 2, m, i - m, i)


@lru_cache(None)
def d_xy(L):
    """RB exp(-i theta Jy): SymPy uses the opposite sign for its argument.

    Integer-spin half-angle monomials have both exponents even or both odd.
    For odd exponents the remaining factor is sin(theta)/2, NOT sin(theta/2).
    This keeps theta = pi/4 free of nested half-angle radicals.
    """
    t = sp.symbols('theta_template', real=True)
    s, c = sp.symbols('half_s half_c', real=True)
    template = wigner_d_small(L, -t)

    def convert(entry):
        polynomial = sp.Poly(ex(entry.xreplace({sp.sin(t / 2): s, sp.cos(t / 2): c})), s, c)
        result = 0
        for (ps, pc), coefficient in polynomial.terms():
            if ps % 2 != pc % 2:
                raise AssertionError('Unexpected integer-spin half-angle parity')
            result += coefficient * ((1 - X) / 2) ** (ps // 2) * ((1 + X) / 2) ** (pc // 2) * (Y / 2 if ps % 2 else 1)
        return ex(result)

    return template.applyfunc(convert)


@lru_cache(None)
def d_at(L, theta):
    return mx(d_xy(L).xreplace({X: sp.cos(theta), Y: sp.sin(theta)}))


def rotation(theta):
    descending = d_at(2, theta)
    return sp.Matrix(5, 5, lambda i, j: descending[2 - M[i], 2 - M[j]])


def first_amplitudes(a, theta=None):
    d = {L: d_xy(L) if theta is None else d_at(L, theta) for L in range(1, 5)}
    return {
        q: sp.Matrix(5, 5, lambda ii, mm: ex(sum(
            sp.Integer(q) ** PI[L - 1] * sp.sqrt(2 * L + 1) * a[L - 1]
            * cg(L, M[ii], M[mm]) * d[L][L - (M[ii] - M[mm]), L - q]
            for L in range(1, 5) if abs(M[ii] - M[mm]) <= L)))
        for q in Q
    }


def strength(a):
    return ex((a.T * a)[0])


def middle_density(amplitudes, weights, S):
    diagonal = sp.diag(*weights)
    return mx(sum((amplitudes[q].T * diagonal * amplitudes[q] for q in Q), sp.zeros(5)) / (2 * S))


def photon_density(amplitudes, weights, S):
    return sp.Matrix(2, 2, lambda aa, bb: ex(sum(
        weights[ii] * amplitudes[Q[aa]][ii, mm] * amplitudes[Q[bb]][ii, mm]
        for ii in range(5) for mm in range(5)) / (2 * S)))


def linear_middle_density(amplitudes, weights, S, analyzer):
    # RB p316: xprime = (A_minus - A_plus)/sqrt(2),
    # yprime = (A_minus + A_plus)/sqrt(2), up to an irrelevant common phase.
    vector_amplitude = (amplitudes[-1] + analyzer * amplitudes[1]) / sp.sqrt(2)
    return mx(vector_amplitude.T * sp.diag(*weights) * vector_amplitude / (2 * S))


def second_vectors(theta):
    d = d_at(2, theta)
    return {q: sp.Matrix([sp.sqrt(5) * d[2 - m, 2 - q] for m in M]) for q in Q}


def second_analyzer(vectors):
    return mx(sum((vectors[q] * vectors[q].T for q in Q), sp.zeros(5)) / 2)


def coherent_probability(amplitudes, vectors, weights, S):
    # Sum over the intermediate m BEFORE taking the squared amplitude.
    result = 0
    for q1 in Q:
        for q2 in Q:
            path = amplitudes[q1] * vectors[q2]
            result += sum(weights[ii] * path[ii] ** 2 for ii in range(5))
    return ex(result / (4 * S))


def population_tensor(K, weights):
    return ex(sum(weights[ii] * sp.Integer(-1) ** (2 - m) * sp.sqrt(5)
                  * clebsch_gordan(2, 2, K, m, -m, 0) for ii, m in enumerate(M)))


def density_tensor(K, q, density):
    return ex(sum(density[ii, jj] * sp.Integer(-1) ** (2 - n) * sp.sqrt(5)
                  * clebsch_gordan(2, 2, K, m, -n, q)
                  for ii, m in enumerate(M) for jj, n in enumerate(M)))


def response(K, L, LP, Ji, Jf):
    # RB Eq3.36; Ji is the initial bra spin in the interaction RME.
    return ex(sp.Integer(-1) ** (1 + Ji - Jf + LP - L - K)
              * sp.sqrt((2 * Ji + 1) * (2 * L + 1) * (2 * LP + 1))
              * clebsch_gordan(L, LP, K, 1, -1, 0) * racah(Ji, Ji, L, LP, K, Jf))


def reduce_direction_polynomial(expression):
    polynomial = sp.Poly(ex(expression), Y)
    return ex(sum(coefficient * Y ** (power[0] % 2) * (1 - X ** 2) ** (power[0] // 2)
                  for power, coefficient in polynomial.terms()))


def spin_matrices():
    plus = sp.zeros(5)
    for ii, m in enumerate(M[:-1]):
        plus[ii + 1, ii] = sp.sqrt(6 - m * (m + 1))
    minus = plus.T
    return (plus + minus) / 2, (plus - minus) / (2 * sp.I), sp.diag(*M)


def spherical_moment(a, b, c):
    if any(power % 2 for power in (a, b, c)):
        return sp.Integer(0)
    return sp.factorial2(a - 1) * sp.factorial2(b - 1) * sp.factorial2(c - 1) / sp.factorial2(a + b + c + 1)


def spherical_average(matrix, xyz):
    def average(entry):
        return ex(sum(coefficient * spherical_moment(*powers)
                      for powers, coefficient in sp.Poly(ex(entry), *xyz).terms()))
    return matrix.applyfunc(average)


def squarefree_certificate(expression):
    """Distinct positive square-free roots and 1 are Q-linearly independent."""
    coefficients = ex(expression).as_coefficients_dict()
    basis = []
    for root, coefficient in coefficients.items():
        if coefficient.is_Rational is not True:
            raise AssertionError('Non-rational root coefficient')
        if root != 1:
            if not (root.is_Pow and root.exp == sp.Rational(1, 2) and root.base.is_Integer and root.base > 0):
                raise AssertionError(f'Unexpected root basis {root}')
            if any(power != 1 for power in sp.factorint(root.base).values()):
                raise AssertionError('Root is not square-free')
        basis.append({'basis': text_scalar(root), 'rational_coefficient': text_scalar(coefficient)})
    return {'basis_coefficients': sorted(basis, key=lambda item: item['basis']),
            'nonzero': any(coefficient != 0 for coefficient in coefficients.values()),
            'proof': 'Distinct positive square-free square roots, together with 1, are linearly independent over Q; at least one rational coefficient is nonzero.'}


def main_result():
    started = time.monotonic()
    checks = {}

    def check(name, condition):
        checks[name] = bool(condition)
        if not checks[name]:
            raise AssertionError(name)

    input_bytes = INPUT.read_bytes()
    prior = json.loads(input_bytes)
    raw_hash = hashlib.sha256(RAW.read_bytes()).hexdigest()
    check('existing_pair_identity_before', hashlib.sha256(input_bytes).hexdigest() == INPUT_SHA)
    check('existing_raw_identity_before', raw_hash == RAW_SHA)
    check('known_initial_weights_normalized', sum(WEIGHTS) == 1)
    check('known_initial_weights_positive_and_aligned', all(w > 0 for w in WEIGHTS) and WEIGHTS == WEIGHTS[::-1])

    U = sp.Matrix([[sp.sympify(value) for value in row] for row in prior['involution']['U']])
    a0 = sp.Matrix([sp.sympify(value) for value in prior['minimal_boundary_pair']['a']])
    a1 = sp.Matrix([sp.sympify(value) for value in prior['exact_pair']['a']])
    pairs = {'pure_boundary': a0, 'full_support': a1}
    check('U_orthogonal_and_involutory', is_zero_matrix(U.T * U - sp.eye(4)) and is_zero_matrix(U * U - sp.eye(4)))
    check('full_support_input_b_matches_Ua', is_zero_matrix(U * a1 - sp.Matrix([sp.sympify(value) for value in prior['exact_pair']['b']])))
    check('pure_boundary_input_b_matches_Ua', is_zero_matrix(U * a0 - sp.Matrix([sp.sympify(value) for value in prior['minimal_boundary_pair']['b']])))

    Jx, Jy, Jz = spin_matrices()
    check('spin2_commutators', is_zero_matrix(Jx * Jy - Jy * Jx - sp.I * Jz))
    theta2 = sp.pi / 4
    vectors = second_vectors(theta2)
    F = second_analyzer(vectors)
    Jk = sp.sin(theta2) * Jx + sp.cos(theta2) * Jz
    F_independent = mx(sp.Rational(5, 6) * Jk ** 2 * (4 * sp.eye(5) - Jk ** 2))
    check('pure_E2_secondary_analyzer_matches_independent_spin_polynomial', is_zero_matrix(F - F_independent))
    check('secondary_trace_is_five', sp.trace(F) == 5)

    nx, ny, nz = sp.symbols('nx ny nz', real=True)
    Jn = nx * Jx + ny * Jy + nz * Jz
    F_sphere = sp.Rational(5, 6) * Jn ** 2 * (4 * sp.eye(5) - Jn ** 2)
    F_average = spherical_average(F_sphere, (nx, ny, nz))
    check('secondary_FULL_solid_angle_average_is_identity', F_average == sp.eye(5))

    coefficient_matrices = {K: sp.Matrix([[sp.sympify(value) for value in row]
                                        for row in prior['source']['validated_exact_response_matrices'][f'R{K}']])
                            for K in (2, 4)}
    for K in (0, 2, 4):
        from_source_formula = sp.Matrix(4, 4, lambda i, j: response(K, i + 1, j + 1, 2, 2))
        check(f'RB_R{K}_formula_matches_existing_coefficient_interface',
              is_zero_matrix(from_source_formula - (sp.eye(4) if K == 0 else coefficient_matrices[K])))
    angular_normalization = {}
    baseline = {}
    expanded = {}
    controls = {}
    tensors = {}
    Z0 = sp.diag(*[sp.Integer(-1) ** m for m in M])

    for name, a in pairs.items():
        b = mx(U * a)
        S = strength(a)
        check(f'{name}_same_positive_strength', S == strength(b) and S > 0)

        angular_records = {}
        for branch, amplitude in (('a', a), ('b', b)):
            generic_A = first_amplitudes(amplitude)
            full_angular_W = reduce_direction_polynomial(sum(
                WEIGHTS[ii] * generic_A[q][ii, mm] ** 2 for ii in range(5) for mm in range(5) for q in Q) / (2 * S))
            predicted = 1 + sum(population_tensor(K, WEIGHTS)
                                * (amplitude.T * coefficient_matrices[K] * amplitude)[0] / S * sp.legendre(K, X)
                                for K in (2, 4))
            check(f'{name}_{branch}_FULL_theta_first_intensity_matches_RB_coefficients', ex(full_angular_W - predicted) == 0)
            check(f'{name}_{branch}_FULL_first_angular_average_is_one', sp.integrate(full_angular_W, (X, -1, 1)) / 2 == 1)
            check(f'{name}_{branch}_first_intensity_has_no_odd_or_higher_than_K4',
                  not full_angular_W.has(Y) and sp.degree(full_angular_W, X) <= 4 and ex(full_angular_W - full_angular_W.xreplace({X: -X})) == 0)
            angular_records[branch] = text_scalar(full_angular_W)
        angular_normalization[name] = angular_records

        for geometry, theta1, destination in (('baseline', sp.Integer(0), baseline), ('expanded_once', sp.pi / 3, expanded)):
            D = rotation(theta1)
            Z = mx(D * Z0 * D.T)
            check(f'{geometry}_spin_rotation_axes_{name}', is_zero_matrix(D * Jz * D.T - sp.sin(theta1) * Jx - sp.cos(theta1) * Jz))
            check(f'{geometry}_Z_orthogonal_involutory_{name}', is_zero_matrix(Z.T * Z - sp.eye(5)) and is_zero_matrix(Z * Z - sp.eye(5)))
            amplitudes_a, amplitudes_b = first_amplitudes(a, theta1), first_amplitudes(b, theta1)
            for q in Q:
                check(f'{geometry}_{name}_amplitude_covariance_q{q}', is_zero_matrix(amplitudes_b[q] + amplitudes_a[q] * Z))
            Ra = middle_density(amplitudes_a, WEIGHTS, S)
            Rb = middle_density(amplitudes_b, WEIGHTS, S)
            check(f'{geometry}_{name}_conditional_spin_rotation_identity', is_zero_matrix(Rb - Z * Ra * Z.T))
            check(f'{geometry}_{name}_single_photon_FULL_polarization_density_equal',
                  is_zero_matrix(photon_density(amplitudes_a, WEIGHTS, S) - photon_density(amplitudes_b, WEIGHTS, S)))
            W1a, W1b = ex(sp.trace(Ra)), ex(sp.trace(Rb))
            Wa, Wb = ex(sp.trace(Ra * F)), ex(sp.trace(Rb * F))
            difference = ex(Wb - Wa)
            check(f'{geometry}_{name}_first_intensities_equal', W1a == W1b)
            for branch, amplitudes, W in (('a', amplitudes_a, Wa), ('b', amplitudes_b, Wb)):
                check(f'{geometry}_{name}_{branch}_trace_agrees_with_COHERENT_path_sum',
                      ex(W - coherent_probability(amplitudes, vectors, WEIGHTS, S)) == 0)
            check(f'{geometry}_{name}_PASSIVE_basis_rotation_leaves_probability_invariant',
                  ex(sp.trace((Z * Ra * Z.T) * (Z * F * Z.T)) - Wa) == 0)
            frame_a, frame_b = mx(D.T * Ra * D), mx(D.T * Rb * D)
            check(f'{geometry}_{name}_gamma1_frame_parity_relation', is_zero_matrix(frame_b - Z0 * frame_a * Z0))
            check(f'{geometry}_{name}_full_secondary_average_recovers_first_intensity',
                  ex(sp.trace(Ra * F_average) - W1a) == 0 and ex(sp.trace(Rb * F_average) - W1b) == 0)
            record = {
                'a': serial_vector(a), 'b_Ua': serial_vector(b), 'S1': text_scalar(S), 'S2': '1',
                'theta1_radians': text_scalar(theta1), 'theta2_radians': 'pi/4', 'phi1_phi2_radians': ['0', '0'],
                'angle_between_photons_radians': text_scalar(abs(theta1 - theta2)),
                'intermediate_M_order': list(M), 'R_a': serial_matrix(Ra), 'R_b': serial_matrix(Rb),
                'R_a_gamma1_frame': serial_matrix(frame_a), 'R_b_gamma1_frame': serial_matrix(frame_b),
                'Z_lab': serial_matrix(Z), 'W1_a': text_scalar(W1a), 'W1_b': text_scalar(W1b),
                'W12_a': text_scalar(Wa), 'W12_b': text_scalar(Wb), 'difference_W12_b_minus_a': text_scalar(difference),
                'conditional_W2_a': text_scalar(Wa / W1a), 'conditional_W2_b': text_scalar(Wb / W1b),
                'difference_conditional_W2_b_minus_a': text_scalar(difference / W1a),
                'numeric_display_only': {'W1': display(W1a), 'W12_a': display(Wa), 'W12_b': display(Wb),
                                         'difference_W12': display(difference), 'conditional_W2_a': display(Wa / W1a),
                                         'conditional_W2_b': display(Wb / W1b), 'difference_conditional_W2': display(difference / W1a)},
            }
            destination[name] = record

            if geometry == 'baseline':
                check(f'baseline_{name}_EXACT_middle_density_equal', Ra == Rb)
                check(f'baseline_{name}_joint_intensities_equal', difference == 0)
                linear = {}
                for axis, sign in (('xprime', -1), ('yprime', 1)):
                    tag_a = linear_middle_density(amplitudes_a, WEIGHTS, S, sign)
                    tag_b = linear_middle_density(amplitudes_b, WEIGHTS, S, sign)
                    check(f'baseline_{name}_linear_{axis}_tag_middle_density_equal', tag_a == tag_b)
                    linear[axis] = {'R_tag_a_equals_R_tag_b': True, 'R_tag_common': serial_matrix(tag_a),
                                    'secondary_joint_intensity_common': text_scalar(ex(sp.trace(tag_a * F)))}
                check(f'baseline_{name}_two_linear_tags_sum_to_unobserved_R',
                      is_zero_matrix(linear_middle_density(amplitudes_a, WEIGHTS, S, -1)
                                     + linear_middle_density(amplitudes_a, WEIGHTS, S, 1) - Ra))
                record['arbitrary_secondary_analyzer_certificate'] = 'R_a = R_b exactly; Tr(R_a F_any) = Tr(R_b F_any) for every fixed secondary analyzer, direction or polarization in this baseline.'
                record['linear_first_tag_control'] = linear
            else:
                certificate = squarefree_certificate(difference)
                check(f'expanded_once_{name}_EXACT_nonzero_joint_discriminant', certificate['nonzero'])
                check(f'expanded_once_{name}_different_middle_densities', not is_zero_matrix(Rb - Ra))
                record['nonzero_difference_certificate'] = certificate
                F_frame = mx(D.T * F * D)
                check(f'expanded_once_{name}_gamma1_frame_trace_agrees', ex(sp.trace(frame_a * F_frame) - Wa) == 0)

                diagonal_a = sp.diag(*[frame_a[ii, ii] for ii in range(5)])
                diagonal_b = sp.diag(*[frame_b[ii, ii] for ii in range(5)])
                dephased_a, dephased_b = mx(D * diagonal_a * D.T), mx(D * diagonal_b * D.T)
                check(f'expanded_once_{name}_IDEAL_gamma1_axis_dephasing_removes_difference', dephased_a == dephased_b)
                random_a, random_b = middle_density(amplitudes_a, RANDOM, S), middle_density(amplitudes_b, RANDOM, S)
                random_frame = mx(D.T * random_a * D)
                check(f'expanded_once_{name}_RANDOM_initial_middle_densities_equal', random_a == random_b)
                check(f'expanded_once_{name}_RANDOM_initial_gamma1_frame_is_diagonal',
                      random_frame == sp.diag(*[random_frame[ii, ii] for ii in range(5)]))
                check(f'expanded_once_{name}_RANDOM_initial_first_intensity_one', ex(sp.trace(random_a)) == 1)
                controls[name] = {
                    'ideal_dephasing': {'definition': 'Rotate R into the gamma1 spin frame, discard every offdiagonal element, and rotate back. This is an ideal diagnostic map, not an experimental deorientation model.',
                                        'dephased_R_a_equals_R_b': True, 'common_dephased_R_lab': serial_matrix(dephased_a),
                                        'common_W12': text_scalar(ex(sp.trace(dephased_a * F))), 'difference_W12': '0'},
                    'random_initial': {'weights': ['1/5'] * 5, 'R_a_equals_R_b': True, 'common_R_lab': serial_matrix(random_a),
                                       'common_R_gamma1_frame': serial_matrix(random_frame), 'common_W1': '1',
                                       'common_W12': text_scalar(ex(sp.trace(random_a * F))), 'difference_W12': '0'},
                }

                odd_K = {f'K{K}_Q{q}': density_tensor(K, q, frame_a)
                         for K in (1, 3) for q in range(-K, K + 1)}
                check(f'expanded_once_{name}_unobserved_first_polarization_has_no_odd_K', all(value == 0 for value in odd_K.values()))
                even_K = {f'K{K}_Q{q}': density_tensor(K, q, frame_a)
                          for K in (0, 2, 4) for q in range(-K, K + 1)}
                nonzero_odd_Q = {key: value for key, value in even_K.items()
                                 if int(key.split('_Q')[1]) % 2 and value != 0}
                check(f'expanded_once_{name}_even_K_tensors_carry_nonzero_odd_Q', bool(nonzero_odd_Q))
                for K in (0, 2, 4):
                    for q in range(-K, K + 1):
                        check(f'expanded_once_{name}_tensor_pi_rotation_K{K}_Q{q}',
                              ex(density_tensor(K, q, frame_b) - sp.Integer(-1) ** q * even_K[f'K{K}_Q{q}']) == 0)
                tensors[name] = {'definition': 'T_KQ(R) = sqrt5 sum_mn R_mn (-1)^(2-n) CG(2,2,K;m,-n,Q). These tensors use the intensity R; divide by W1 for normalized conditional statistical tensors.',
                                 'all_odd_K_values_zero': True,
                                 'nonzero_odd_Q_in_even_K': {key: text_scalar(value) for key, value in nonzero_odd_Q.items()},
                                 'mechanism': 'In the gamma1 frame Z0 flips odd magnetic-projection coherences, equivalently odd Q components within even K tensors. It preserves diagonal populations and even Q. Odd Q is not an odd K tensor.'}

    pure_base = baseline['pure_boundary']
    expected_baseline_R = sp.diag(1, 5, 3, 5, 1) / 16
    check('pure_baseline_R_is_explicit_diagonal_certificate',
          pure_base['R_a'] == serial_matrix(expected_baseline_R))
    check('pure_baseline_intensity_values', pure_base['W1_a'] == '15/16' and pure_base['W12_a'] == '55/64')
    pure_expanded = expanded['pure_boundary']
    check('pure_expanded_W1_129_over_128', pure_expanded['W1_a'] == '129/128')
    check('pure_expanded_difference_45_over_256', pure_expanded['difference_W12_b_minus_a'] == '45/256')
    check('pure_expanded_conditional_difference_15_over_86', pure_expanded['difference_conditional_W2_b_minus_a'] == '15/86')

    # Independent phase audit where compact RB3.73 actually applies:
    # random initial state, no other selected axis, M1/E2 first gamma.
    delta = sp.Rational(1, 2)
    phase_a = sp.Matrix([1, delta, 0, 0])
    phase_A = first_amplitudes(phase_a, sp.Integer(0))
    phase_R = middle_density(phase_A, RANDOM, strength(phase_a))
    check('phase_control_random_initial_first_intensity_one', sp.trace(phase_R) == 1)
    check('phase_control_gamma1_axis_middle_density_diagonal', phase_R == sp.diag(*[phase_R[ii, ii] for ii in range(5)]))
    phase_records = {}
    phase_W, wrong_W = 0, 0
    for K in (0, 2, 4):
        direct_B = population_tensor(K, tuple(phase_R[ii, ii] for ii in range(5)))
        R11, R12, R22 = (response(K, L, LP, 2, 2) for L, LP in ((1, 1), (1, 2), (2, 2)))
        correct_B = ex((R11 - 2 * delta * R12 + delta ** 2 * R22) / (1 + delta ** 2))
        incorrect_B = ex((R11 + 2 * delta * R12 + delta ** 2 * R22) / (1 + delta ** 2))
        check(f'phase_control_K{K}_DIRECT_amplitude_matches_RB_minus_2delta', direct_B == correct_B)
